def parse_simple_csv(csv_text: str) -> list[dict]:
    if not csv_text.strip():
        return []

    lines = csv_text.strip().split('\n')
    headers = lines[0].split(',')
    headers = [header.strip() for header in headers]

    result = []
    for line in lines[1:]:
        if line.strip():
            values = line.split(',')
            values = [value.strip() for value in values]
            for i in range(len(values)):
                if values[i].startswith('"') and values[i].endswith('"'):
                    values[i] = values[i][1:-1].replace('""', '"')
            result.append(dict(zip(headers, values)))

    return result

def safe_json_path_lookup(data: dict | list, path: str, default: any = None) -> any:
    if not path:
        return data

    components = path.split('.')
    current = data

    for component in components:
        try:
            if isinstance(current, dict):
                current = current[component]
            elif isinstance(current, list):
                current = current[int(component)]
            else:
                return default
        except (KeyError, IndexError):
            return default

    return current

def compact_number_formatter(n: int | float) -> str:
    if n == 0:
        return "0"
    if n < 0:
        return "-" + compact_number_formatter(-n)

    suffixes = ['K', 'M', 'B']
    for suffix in suffixes:
        if abs(n) >= 1000:
            n /= 1000
        else:
            break
    return f"{n:.1f}{suffix}" if n >= 10 else f"{n:.0f}{suffix}"

def validate_password_strength(pw: str) -> dict:
    criteria = {
        'length': len(pw) >= 8,
        'uppercase': any(c.isupper() for c in pw),
        'lowercase': any(c.islower() for c in pw),
        'digit': any(c.isdigit() for c in pw),
        'special': any(c in '!@#$%^&*()-_=+[]{}' for c in pw)
    }
    score = sum(criteria.values())
    missing = [key for key, value in criteria.items() if not value]
    return {"valid": score == 5, "score": score, "missing": missing}

def time_diff_humanized(seconds: int) -> str:
    if seconds == 0:
        return "0s"

    units = [
        (86400, 'd'),
        (3600, 'h'),
        (60, 'm'),
        (1, 's')
    ]

    result = []
    for count, unit in units:
        value = seconds // count
        if value > 0:
            result.append(f"{value}{unit}")
            seconds %= count

    return ' '.join(result)

def find_first_missing_positive(nums: list[int]) -> int:
    n = len(nums)
    contains_one = False

    # Check if 1 is present in the array
    for num in nums:
        if num == 1:
            contains_one = True
            break
    if not contains_one:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index+1 is the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers are present
    return n + 1

def calculate_tax_bracket(income: float, brackets: list[tuple[float, float]]) -> float:
    if income <= 0:
        return 0.0

    total_tax = 0.0
    for upper_limit, rate in brackets:
        if income <= upper_limit:
            tax = (income - (income if income < upper_limit else 0)) * rate
            total_tax += tax
            break
        else:
            tax = (upper_limit - (income if income < upper_limit else 0)) * rate
            total_tax += tax
            income -= upper_limit

    return round(total_tax, 2)

def fuzzy_search_score(pattern: str, text: str) -> int:
    pattern = pattern.lower()
    text = text.lower()
    pattern_len = len(pattern)
    text_len = len(text)

    if pattern_len == 0:
        return 0

    score = 0
    i, j = 0, 0

    while i < pattern_len and j < text_len:
        if pattern[i] == text[j]:
            score += 10
            if i > 0 and pattern[i] == pattern[i - 1]:
                score += 15
            if j == 0 or text[j - 1] in " _-":
                score += 20
            i += 1
        j += 1

    return score

def simple_caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isalpha():
            shift_base = 'A' if char.isupper() else 'a'
            result.append(chr((ord(char) - ord(shift_base) + shift) % 26 + ord(shift_base)))
        else:
            result.append(char)
    return ''.join(result)

def matrix_transpose_ragged(matrix: list[list[any]], fill_value: any = None) -> list[list[any]]:
    if not matrix:
        return []

    max_length = max(len(row) for row in matrix)
    transposed = []

    for col in range(max_length):
        transposed_row = []
        for row in matrix:
            if col < len(row):
                transposed_row.append(row[col])
            else:
                transposed_row.append(fill_value)
        transposed.append(transposed_row)

    return transposed

from itertools import groupby

def run_length_compress(data: list[int]) -> list[tuple[int, int]]:
    if not data:
        return []
    return [(value, sum(1 for _ in group)) for value, group in groupby(data)]

def parse_duration_string(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0

    for part in s.split():
        if len(part) < 2 or part[-1] not in units:
            raise ValueError("Invalid unit")

        value = int(part[:-1])
        if value < 0:
            raise ValueError("Negative value")

        total_seconds += value * units[part[-1]]

    return total_seconds

class CircularBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.head = 0
        self.tail = 0
        self.size = 0

    def enqueue(self, item: any) -> bool:
        if self.is_full():
            return False
        self.buffer[self.tail] = item
        self.tail = (self.tail + 1) % self.capacity
        self.size += 1
        return True

    def dequeue(self) -> any:
        if self.is_empty():
            raise IndexError("Buffer is empty")
        item = self.buffer[self.head]
        self.buffer[self.head] = None
        self.head = (self.head + 1) % self.capacity
        self.size -= 1
        return item

    def peek(self) -> any:
        if self.is_empty():
            raise IndexError("Buffer is empty")
        return self.buffer[self.head]

    def is_full(self) -> bool:
        return self.size == self.capacity

    def is_empty(self) -> bool:
        return self.size == 0

    def size(self) -> int:
        return self.size

def deep_merge_dicts(base: dict, update: dict) -> dict:
    for key, value in update.items():
        if key in base and isinstance(base[key], dict) and isinstance(value, dict):
            base[key] = deep_merge_dicts(base[key], value)
        else:
            base[key] = value
    return base

def retry_with_backoff_simulator(attempts_needed: int, max_retries: int, base_delay: float = 1.0, factor: float = 2.0, max_delay: float = 60.0) -> tuple[bool, float, list[float]]:
    if attempts_needed <= max_retries + 1:
        delays = []
        total_delay = 0.0
        for k in range(1, attempts_needed):
            delay = min(base_delay * (factor ** (k - 1)), max_delay)
            delays.append(round(delay, 2))
            total_delay += delay
        return (True, total_delay, delays)
    else:
        return (False, 0.0, [])

def evaluate_simple_expression(expr: str) -> int:
    # Remove whitespace from the expression
    expr = expr.replace(" ", "")

    # Check for division by zero
    if '/' in expr:
        if '0/' in expr or '/0' in expr:
            raise ZeroDivisionError("Division by zero is not allowed")

    # Evaluate the expression using Python's eval function
    result = eval(expr)

    return int(result)
